import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const TYPE_APPROVAL = '전자결재';
const TYPE_BOARD = '게시판';

function intOf(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr03902Controller {
  @Get('/employees/:employeeId/activities')
  async listEmployeeActivities(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const employeeId = req.params['employeeId'];
    const page = intOf(query['page'], 0);
    let size = intOf(query['size'], DEFAULT_SIZE);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const rawType = query['activityType'];
    const activityType = rawType === undefined || rawType === null || rawType === '' ? '' : String(rawType);
    if (activityType !== '' && activityType !== TYPE_APPROVAL && activityType !== TYPE_BOARD) {
      throw new ApiError(400, 'VALIDATION_FAILED', '활동 구분은 전자결재 또는 게시판이어야 합니다.');
    }
    if (!/^[0-9]+$/.test(employeeId)) {
      throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const viewers = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      const targets = await db.query(
        'SELECT employee_id AS "employeeId", department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (viewers.length === 0 || targets.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      const scopes = await db.query(
        'SELECT view_scope AS "viewScope" FROM menu_permission WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      // 가정: 메뉴 구분 없이 조회자에게 부여된 가장 넓은 조회 범위를 권한 범위로 본다. 본인 활동은 항상 조회 가능.
      const scopeNames = scopes.map((s: any) => String(s.viewScope));
      const sameDept = Number(viewers[0].departmentId) === Number(targets[0].departmentId);
      const isSelf = String(targets[0].employeeId) === String(user.id);
      const inScope =
        isSelf ||
        scopeNames.includes('전체') ||
        (scopeNames.includes('부서') && sameDept);
      if (!inScope) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      // 가정: 부서 공개 게시물은 조회자와 대상이 같은 부서일 때만, 기안 상태 문서는 기안자 본인만 열람한다.
      const params = {
        userId: user.id,
        employeeId,
        sameDept: sameDept ? 'true' : 'false',
        size,
        offset: page * size,
      };
      const approvalSelect =
        'SELECT CAST(:approvalLabel AS text) AS "activityType", d.title AS "title", d.created_at AS "activityAt" ' +
        'FROM approval_document d ' +
        'WHERE d.drafter_id = CAST(:employeeId AS bigint) ' +
        'AND (d.approval_status <> CAST(:draftStatus AS text) OR d.drafter_id = CAST(:userId AS bigint))';
      const boardSelect =
        'SELECT CAST(:boardLabel AS text) AS "activityType", b.title AS "title", b.created_at AS "activityAt" ' +
        'FROM board_post b ' +
        'WHERE b.author_id = CAST(:employeeId AS bigint) ' +
        'AND (b.visibility_scope = CAST(:allScope AS text) OR b.author_id = CAST(:userId AS bigint) ' +
        'OR (b.visibility_scope = CAST(:deptScope AS text) AND CAST(:sameDept AS boolean)))';
      const approvalCount =
        'SELECT COUNT(*) AS "cnt" FROM approval_document d ' +
        'WHERE d.drafter_id = CAST(:employeeId AS bigint) ' +
        'AND (d.approval_status <> CAST(:draftStatus AS text) OR d.drafter_id = CAST(:userId AS bigint))';
      const boardCount =
        'SELECT COUNT(*) AS "cnt" FROM board_post b ' +
        'WHERE b.author_id = CAST(:employeeId AS bigint) ' +
        'AND (b.visibility_scope = CAST(:allScope AS text) OR b.author_id = CAST(:userId AS bigint) ' +
        'OR (b.visibility_scope = CAST(:deptScope AS text) AND CAST(:sameDept AS boolean)))';
      const fixed = {
        approvalLabel: TYPE_APPROVAL,
        boardLabel: TYPE_BOARD,
        draftStatus: '기안',
        allScope: '전체',
        deptScope: '부서',
      };
      const selects: string[] = [];
      let total = 0;
      if (activityType === '' || activityType === TYPE_APPROVAL) {
        selects.push(approvalSelect);
        const rows = await db.query(approvalCount, { ...params, ...fixed });
        total += Number(rows[0].cnt);
      }
      if (activityType === '' || activityType === TYPE_BOARD) {
        selects.push(boardSelect);
        const rows = await db.query(boardCount, { ...params, ...fixed });
        total += Number(rows[0].cnt);
      }
      const sql =
        selects.join(' UNION ALL ') +
        ' ORDER BY "activityAt" DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)';
      const items = await db.query(sql, { ...params, ...fixed });
      await db.execute(
        'INSERT INTO personal_info_access_log (employee_id, target_employee_id, target_info_type, access_type, accessed_at, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), CAST(:employeeId AS bigint), :infoType, :accessType, now(), now(), now())',
        { userId: user.id, employeeId, infoType: '업무활동', accessType: '조회' },
      );
      return { items, page, size, total };
    });
  }
}

