import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Pairs,
  Field,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03902Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [activityType, setActivityType] = useState('');
  const [activityPage, setActivityPage] = useState(0);

  const list = useData<Page>(
    () => call<Page>('GET', '/employees', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );

  const activities = useData<Page>(
    () => {
      if (!selected) {
        return Promise.resolve({ items: [], page: 0, size: SIZE, total: 0 } as Page);
      }
      return call<Page>('GET', '/employees/' + String(selected.employeeId) + '/activities', role, undefined, {
        activityType,
        page: activityPage,
        size: SIZE,
      });
    },
    [role, selected, activityType, activityPage],
  );

  function search() {
    setPage(0);
    setApplied({ employmentStatus: status, departmentId });
  }

  function reset() {
    setStatus('');
    setDepartmentId('');
    setPage(0);
    setApplied({});
  }

  function open(row: Row) {
    setActivityType('');
    setActivityPage(0);
    setSelected(row);
    notify('조직원 활동 내역을 불러왔습니다.');
  }

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>프로필</h2>
          <Pairs
            items={[
              ['사번', String(selected.employeeNo ?? '')],
              ['임직원명', String(selected.name ?? '')],
              ['주부서', <RefName table="department" role={role} value={selected.departmentId} />],
              ['재직 구분', <Badge value={selected.employmentStatus} />],
              ['이메일', String(selected.email ?? '')],
              ['휴대전화번호', String(selected.mobilePhone ?? '')],
            ]}
          />
        </section>
        <section className="box">
          <h2>업무활동 내역</h2>
          <Filters
            onSearch={() => setActivityPage(0)}
            onReset={() => {
              setActivityType('');
              setActivityPage(0);
            }}
          >
            <Field label="활동 구분">
              <Select
                value={activityType}
                onChange={(v) => {
                  setActivityType(v);
                  setActivityPage(0);
                }}
                options={[
                  ['전자결재', '전자결재'],
                  ['게시판', '게시판'],
                ]}
                placeholder="전체"
              />
            </Field>
          </Filters>
          {activities.error ? <ErrorText text={activities.error} /> : null}
          <Band total={activities.data?.total} />
          <DataTable
            columns={[
              { key: 'activityType', label: '활동 유형', render: (r) => <Badge value={r.activityType} /> },
              { key: 'title', label: '문서·게시물 제목' },
              { key: 'activityAt', label: '활동 일시', render: (r) => <DateText value={r.activityAt} time /> },
            ]}
            rows={activities.data?.items ?? []}
            empty="조회할 수 있는 업무활동 내역이 없습니다."
          />
          <Pager
            page={activityPage}
            size={SIZE}
            total={activities.data?.total ?? 0}
            onPage={setActivityPage}
          />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>조직원 검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="재직 구분">
            <Select
              value={status}
              onChange={setStatus}
              options={[
                ['재직자', '재직자'],
                ['퇴직자', '퇴직자'],
              ]}
              placeholder="전체"
            />
          </Field>
          <Field label="주부서">
            <LookupSelect
              table="department"
              role={role}
              value={departmentId}
              onChange={setDepartmentId}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={list.data?.total} />
        <DataTable
          columns={[
            { key: 'employeeNo', label: '사번' },
            { key: 'name', label: '임직원명' },
            {
              key: 'departmentId',
              label: '주부서',
              render: (r) => <RefName table="department" role={role} value={r.departmentId} />,
            },
            { key: 'employmentStatus', label: '재직 구분', render: (r) => <Badge value={r.employmentStatus} /> },
          ]}
          rows={list.data?.items ?? []}
          onRowClick={open}
          empty="검색 결과가 없습니다. 조건을 바꿔 다시 검색해 주세요."
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}
